class Graph:
    def __init__(self, graph_dict=None, directed=True):
        self.graph_dict = graph_dict or {}
        self.directed = directed
        if not directed:
            self.make_undirected()

    def make_undirected(self):
        """Make a directed graph into an undirected graph by adding symmetric edges."""
        for a in list(self.graph_dict.keys()):
            for (b, dist) in self.graph_dict[a].items():
                self.add_edge(b, a, dist)

    def add_vertex(self, vertex):
        """Add a vertex to the graph."""
        if vertex not in self.graph_dict:
            self.graph_dict[vertex] = {}

    def add_edge(self, start, end, distance=1):
        """Add a directed edge to the graph."""
        self.graph_dict[start][end] = distance
        if not self.directed:
            self.graph_dict[end][start] = distance

    def bfs(self, start):
        """Return a list of vertices that BFS reaches, starting from start vertex."""
        from collections import deque
        visited = []
        queue = deque([start])
        while queue:
            vertex = queue.popleft()
            if vertex not in visited:
                visited.append(vertex)
                for next_vertex in self.graph_dict[vertex]:
                    queue.append(next_vertex)
        return visited

def bfs_path_search(graph, start, end):
    """Return a list of vertices that BFS reaches, starting from start vertex, including the goal vertex if found."""
    if start not in graph.graph_dict or end not in graph.graph_dict:
        raise ValueError("Start or end vertex not in the graph")

    visited = set()
    queue = [(start, [start])]

    while queue:
        (vertex, path) = queue.pop(0)
        visited.add(vertex)

        # If the end vertex is found, we return the path
        if vertex == end:
            return path

        # If not, we continue to search
        for next_vertex in graph.graph_dict[vertex]:
            if next_vertex not in visited:
                new_path = path + [next_vertex]
                queue.append((next_vertex, new_path))

    return None

# Example usage:
