def heuristic(node1, node2):
    """ Heuristic function (Manhattan distance in this case) """
    x1, y1 = node1
    x2, y2 = node2
    return abs(x1 - x2) + abs(y1 - y2)

def astar(start, goal, graph):
    """ A* Search Algorithm """
    # Open list for storing nodes to be evaluated
    open_list = []
    heapq.heappush(open_list, (0, start))

    # Closed list to store explored nodes
    closed_list = set()

    # Each node has a g_score (cost from start to node) and f_score (g_score + h_score)
    g_scores = {start: 0}
    f_scores = {start: heuristic(start, goal)}

    came_from = {}

    while open_list:
        # Get the node with the lowest f_score
        current_f, current_node = heapq.heappop(open_list)

        if current_node == goal:
            # Reconstruct the path
            path = [current_node]
            while current_node in came_from:
                current_node = came_from[current_node]
                path.append(current_node)
            path.reverse()
            return path

        closed_list.add(current_node)

        # Explore the neighbors of the current node
        for neighbor, cost in graph[current_node].items():
            if neighbor in closed_list:
                continue

